  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOQL Injection Vulnerability",
      "severity": "High",
      "file": "AccountSearchController.cls",
      "lines": "6",
      "explanation": "The searchAccounts method constructs a SOQL query by concatenating the user-provided searchKey directly into the query string without any sanitization or binding. This allows an attacker to inject malicious SOQL syntax and potentially access unauthorized data.",
      "remediation": "Replace the dynamic query construction with a bind variable approach: 'SELECT Id, Name, Industry FROM Account WHERE Name LIKE :searchKey LIMIT 50'. Remove the AccessLevel.USER_MODE parameter as it's not needed for this type of query."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C1",
      "title": "SOSL Injection in InvoiceSearchController",
      "severity": "High",
      "file": "InvoiceSearchController.cls",
      "lines": "4",
      "explanation": "The input parameter 'invoiceNum' is directly concatenated into a SOSL search term without any sanitization or binding. This creates a potential SOSL injection vulnerability where malicious input could alter the query's behavior.",
      "remediation": "Use a bind variable for the search term instead of concatenating it directly. For example, use 'FIND :searchTerm IN ALL FIELDS RETURNING Invoice__c(...)' where searchTerm is properly bound."
    }
  ]
}
