{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "CRUD/FLS violations",
      "severity": "High",
      "file": "AccountRatingService.cls",
      "lines": "6, 12",
      "explanation": "The code performs a SOQL query and DML operation without enforcing CRUD or FLS checks. The query reads AnnualRevenue and Rating fields, which may not be accessible to the user due to field-level security. Similarly, the update operation does not validate field permissions, allowing potential modification of fields the user should not have access to.",
      "remediation": "Add WITH USER_MODE to the SOQL query and use Security.stripInaccessible() on the retrieved records before performing DML operations. Alternatively, explicitly check CRUD permissions using Security.isCreateAllowed(), Security.isUpdateAllowed(), etc."
    },
    {
      "category": "C3",
      "title": "Sharing violation",
      "severity": "Medium",
      "file": "AccountRatingService.cls",
      "lines": "1",
      "explanation": "Although the class is declared with sharing, it is @AuraEnabled and thus reachable from an external entry point. If invoked by a user without proper record-level sharing access, it could bypass sharing rules.",
      "remediation": "Ensure that classes reachable via @AuraEnabled are properly secured with appropriate sharing modes or use WITH SECURITY_ENFORCED in queries."
    }
  ]
}

{
  "vulnerable": true,
  "findings": [
    {
      "category": "C2",
      "title": "CRUD/FLS violations in Task creation",
      "severity": "High",
      "file": "CaseEscalationService.cls",
      "lines": "17",
      "explanation": "The code attempts to insert a Task without checking if the user has create permissions on the Task object or if the fields being set (Subject, Status, Priority, WhatId) are allowed for the user. The DmlException is silently caught, hiding potential FLS violations from the caller.",
      "remediation": "Add explicit CRUD/FLS checks using Security.isCreateable() and Security.stripInaccessible() before inserting the Task, or enforce USER_MODE in the insert operation."
    },
    {
      "category": "C4",
      "title": "Excessive permissions in permission set",
      "severity": "Medium",
      "file": "Case_Escalation_Agent.permissionset-meta.xml",
      "lines": "classAccesses",
      "explanation": "The permission set grants access to the CaseEscalationService class but does not grant create permissions on Task, which is needed for the service to function. However, it also lacks explicit field-level permissions for Task fields that are being used.",
      "remediation": "Ensure the permission set explicitly grants necessary object and field permissions for Task creation, or remove access to the class if it cannot be properly secured."
    }
  ]
}

